import { test, expect } from '@playwright/test';

test.describe('File Upload - Maximum Size Limit Error', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should display error message when file exceeds maximum size limit', async ({ page }) => {
    // Setup: intercept the file upload API call
    await page.route('**/api/upload', (route) => {
      route.abort('File too large');
    });

    // Locate and interact with file input using getByLabel
    const fileInput = page.getByLabel('Upload file');
    await expect(fileInput).toBeVisible();
    await fileInput.setInputFiles('fixtures/large-file.zip');

    // Verify error message appears
    const errorMessage = page.getByText('File size exceeds maximum limit');
    await expect(errorMessage).toBeVisible();

    // Verify error icon is displayed
    const errorIcon = page.getByRole('img', { name: /error/i });
    await expect(errorIcon).toBeVisible();

    // Verify error message is visible
    await expect(errorMessage).toBeVisible();

    // Verify file input is still visible
    await expect(fileInput).toBeVisible();
  });

  test('should not display error message when file is within size limit', async ({ page }) => {
    // Setup: intercept the file upload API call
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Locate and interact with file input using getByLabel
    const fileInput = page.getByLabel('Upload file');
    await expect(fileInput).toBeVisible();
    await fileInput.setInputFiles('fixtures/small-file.txt');

    // Verify error message does not appear
    const errorMessage = page.getByText('File size exceeds maximum limit');
    await expect(errorMessage).not.toBeVisible();

    // Verify success message appears
    const successMessage = page.getByText('File uploaded successfully');
    await expect(successMessage).toBeVisible();

    // Verify file input is still visible
    await expect(fileInput).toBeVisible();
  });
});
